import{_ as p,a0 as o,w as l,s as d,ao as c,I as t,x as i,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中将文件编码转换为 UTF-8 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中将文件编码转换为 UTF-8 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中将文件编码转换为 UTF-8 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中将文件编码转换为 UTF-8 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux","title":"如何在 Linux 中将文件编码转换为 UTF-8","tag":"201611","desc":""},"relativePath":"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux.md","filePath":"[post].md"}'),r={name:"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux.md"};function h(u,s,g,k,f,b){const n=o("Link");return l(),d("div",null,[s[13]||(s[13]=c(`<h1 id="如何在-linux-中将文件编码转换为-utf-8" tabindex="-1">如何在 Linux 中将文件编码转换为 UTF-8 <a class="header-anchor" href="#如何在-linux-中将文件编码转换为-utf-8" aria-label="Permalink to “如何在 Linux 中将文件编码转换为 UTF-8”">​</a></h1><p>在这篇教程中，我们将解释字符编码的含义，然后给出一些使用命令行工具将使用某种字符编码的文件转化为另一种编码的例子。最后，我们将一起看一看如何在 Linux 下将使用各种字符编码的文件转化为 UTF-8 编码。</p><p>你可能已经知道，计算机除了二进制数据，是不会理解和存储字符、数字或者任何人类能够理解的东西的。一个二进制位只有两种可能的值，也就是 <code>0</code> 或 <code>1</code>，<code>真</code>或<code>假</code>，<code>是</code>或<code>否</code>。其它的任何事物，比如字符、数据和图片，必须要以二进制的形式来表现，以供计算机处理。</p><p>简单来说，字符编码是一种可以指示电脑来将原始的 0 和 1 解释成实际字符的方式，在这些字符编码中，字符都以一串数字来表示。</p><p>字符编码方案有很多种，比如 ASCII、ANCI、Unicode 等等。下面是 ASCII 编码的一个例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>字符            二进制</span></span>
<span class="line"><span>A               01000001</span></span>
<span class="line"><span>B               01000010</span></span></code></pre></div><p>在 Linux 中，命令行工具 <code>iconv</code> 用来将使用一种编码的文本转化为另一种编码。</p><p>你可以使用 <code>file</code> 命令，并添加 <code>-i</code> 或 <code>--mime</code> 参数来查看一个文件的字符编码，这个参数可以让程序像下面的例子一样输出字符串的 mime (Multipurpose Internet Mail Extensions) 数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file -i Car.java</span></span>
<span class="line"><span>$ file -i CarDriver.java</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/Check-File-Encoding-in-Linux.png" alt="在 Linux 中查看文件的编码"></p><p><em>在 Linux 中查看文件的编码</em></p><p>iconv 工具的使用方法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iconv option</span></span>
<span class="line"><span>$ iconv options -f from-encoding -t to-encoding inputfile(s) -o outputfile</span></span></code></pre></div><p>在这里，<code>-f</code> 或 <code>--from-code</code> 表明了输入编码，而 <code>-t</code> 或 <code>--to-encoding</code> 指定了输出编码。</p><p>为了列出所有已有编码的字符集，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iconv -l</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/List-Coded-Charsets-in-Linux.png" alt="列出所有已有编码字符集"></p><p><em>列出所有已有编码字符集</em></p><h3 id="将文件从-iso-8859-1-编码转换为-utf-8-编码" tabindex="-1">将文件从 ISO-8859-1 编码转换为 UTF-8 编码 <a class="header-anchor" href="#将文件从-iso-8859-1-编码转换为-utf-8-编码" aria-label="Permalink to “将文件从 ISO-8859-1 编码转换为 UTF-8 编码”">​</a></h3><p>下面，我们将学习如何将一种编码方案转换为另一种编码方案。下面的命令将会将 ISO-8859-1 编码转换为 UTF-8 编码。</p><p>考虑如下文件 <code>input.file</code>，其中包含这几个字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>� � � �</span></span></code></pre></div><p>我们从查看这个文件的编码开始，然后来查看文件内容。最后，我们可以把所有字符转换为 UTF-8 编码。</p><p>在运行 <code>iconv</code> 命令之后，我们可以像下面这样检查输出文件的内容，和它使用的字符编码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file -i input.file</span></span>
<span class="line"><span>$ cat input.file </span></span>
<span class="line"><span>$ iconv -f ISO-8859-1 -t UTF-8//TRANSLIT input.file -o out.file</span></span>
<span class="line"><span>$ cat out.file </span></span>
<span class="line"><span>$ file -i out.file</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/Converts-UTF8-to-ASCII-in-Linux.png" alt="在 Linux 中将 ISO-8859-1 转化为 UTF-8"></p><p><em>在 Linux 中将 ISO-8859-1 转化为 UTF-8</em></p><p>注意：如果输出编码后面添加了 <code>//IGNORE</code> 字符串，那些不能被转换的字符将不会被转换，并且在转换后，程序会显示一条错误信息。</p><p>好，如果字符串 <code>//TRANSLIT</code> 被添加到了上面例子中的输出编码之后 (<code>UTF-8//TRANSLIT</code>)，待转换的字符会尽量采用形译原则。也就是说，如果某个字符在输出编码方案中不能被表示的话，它将会被替换为一个形状比较相似的字符。</p><p>而且，如果一个字符不在输出编码中，而且不能被形译，它将会在输出文件中被一个问号标记 <code>?</code> 代替。</p><h3 id="将多个文件转换为-utf-8-编码" tabindex="-1">将多个文件转换为 UTF-8 编码 <a class="header-anchor" href="#将多个文件转换为-utf-8-编码" aria-label="Permalink to “将多个文件转换为 UTF-8 编码”">​</a></h3><p>回到我们的主题。如果你想将多个文件甚至某目录下所有文件转化为 UTF-8 编码，你可以像下面一样，编写一个简单的 shell 脚本，并将其命名为 <code>encoding.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>### 将 values_here 替换为输入编码</span></span>
<span class="line"><span>FROM_ENCODING=&quot;value_here&quot;</span></span>
<span class="line"><span>### 输出编码 (UTF-8)</span></span>
<span class="line"><span>TO_ENCODING=&quot;UTF-8&quot;</span></span>
<span class="line"><span>### 转换命令</span></span>
<span class="line"><span>CONVERT=&quot; iconv  -f   $FROM_ENCODING  -t   $TO_ENCODING&quot;</span></span>
<span class="line"><span>### 使用循环转换多个文件</span></span>
<span class="line"><span>for  file  in  *.txt; do</span></span>
<span class="line"><span>$CONVERT   &quot;$file&quot;   -o  &quot;\${file%.txt}.utf8.converted&quot;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>保存文件，然后为它添加可执行权限。在待转换文件 (*.txt) 所在的目录中运行这个脚本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod  +x  encoding.sh</span></span>
<span class="line"><span>$ ./encoding.sh</span></span></code></pre></div><p>重要事项：你也可以使这个脚本变得更通用，比如转换任意特定的字符编码到另一种编码。为了达到这个目的，你只需要改变 <code>FROM_ENCODING</code> 及 <code>TO_ENCODING</code> 变量的值。别忘了改一下输出文件的文件名 <code>&quot;\${file%.txt}.utf8.converted&quot;</code>.</p><p>若要了解更多信息，可以查看 <code>iconv</code> 的手册页 (man page)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man iconv</span></span></code></pre></div><p>将这篇指南总结一下，理解字符编码的概念、了解如何将一种编码方案转换为另一种，是一个电脑用户处理文本时必须要掌握的知识，程序员更甚。</p><p>最后，你可以在下面的评论部分中与我们联系，提出问题或反馈。</p><hr>`,41)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),e(n,{href:"http://www.tecmint.com/convert-files-to-utf-8-encoding-in-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("http://www.tecmint.com/convert-files-to-utf-8-encoding-in-linux/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),e(n,{href:"http://www.tecmint.com/author/aaronkili/"},{default:a(()=>[...s[2]||(s[2]=[i("Aaron Kili",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),e(n,{href:"https://github.com/StdioA"},{default:a(()=>[...s[3]||(s[3]=[i("StdioA",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const C=p(r,[["render",h]]);export{x as __pageData,C as default};
